// src/index.js
require_main().config();
var fastify = require_fastify()({ logger: true });
var cors = require_cors();
var fastifyWebsocket = require_websocket2();
var { Pool } = require_lib3();
var { connect: connectNats } = require_nats2();
var Redis = require_built3();
var DATABASE_URL = process.env.DATABASE_URL || "postgresql://postgres:postgres@localhost:5432/postgres";
var REDIS_URL = process.env.REDIS_URL || "redis://localhost:6379";
var NATS_URL = process.env.NATS_URL || "nats://localhost:4222";
var pool = new Pool({ connectionString: DATABASE_URL });
var redisSubscriber = new Redis(REDIS_URL);
var nc;
async function start() {
  await fastify.register(cors, {
    origin: "*"
  });
  await fastify.register(fastifyWebsocket);
  try {
    nc = await connectNats({ servers: NATS_URL });
    fastify.log.info(`Connected to NATS at ${NATS_URL}`);
  } catch (err) {
    fastify.log.error(`Failed to connect to NATS: ${err}`);
  }
  fastify.decorate("db", pool);
  fastify.decorate("nc", nc);
  fastify.decorate("redisSub", redisSubscriber);
  fastify.register(require_projects(), { prefix: "/api/projects" });
  fastify.register(require_websockets(), { prefix: "/ws" });
  try {
    await fastify.listen({ port: 3e3, host: "0.0.0.0" });
    fastify.log.info("Server listening on port 3000");
  } catch (err) {
    fastify.log.error(err);
    process.exit(1);
  }
}
start();
